// Этап 5.25a: петля добычи мира 1 на ядре core/world1.mjs без O — бот касаниями проходит задания 1–3 новой игры.
// Новая игра: первый экран этажа 1 из rollScreen(1, makeRng(1)) (раскладка не обязана совпадать с O — это 5.25b), клетки сводки — по нулевым уровням.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { makeWorld1 } from '../core/world1.mjs';
import { makeFloors } from '../core/floors.mjs';
import { makeStats } from '../core/stats.mjs';
import { makeUpgrades } from '../core/upgrades.mjs';
import { makeRng } from '../core/rng.mjs';
import { loadData } from '../oracle/mine525a/check525a.mjs';

const CELLS = ['pickaxeDamage', 'attackSpeed', 'clickRadius', 'expGainMulti', 'floorClearRequirementMulti'];
const FRAME_CAP = 60000;

function newGame(data) {
  const rng = makeRng(1);
  const screen = makeFloors(data.mining).rollScreen(1, rng).rocks;
  const rocks = { n: screen.length };
  for (const f of ['hp', 'x', 'y', 'ore', 'size', 'zone']) rocks[f] = screen.map((r) => r[f]);
  const e = makeStats(data.stats, data.statrules);
  e.settle();
  const levels = Array(data.upgrades.constants.rowCount).fill(0);
  return { rocks, ore: Array(26).fill(0), bar: Array(16).fill(0), xp: 0, level: 1, task: 1, taskProgress: 0, screen: 1, floorsOpen: 1,
    clears: 0, stats: Object.fromEntries(CELLS.map((k) => [k, e.get('stat.' + k)])), levels, t: 2, rng };
}

// самый плотный живой камень: точка касания (x, y + 80) попадает в квадрат досягаемости наибольшего числа живых камней
function target(s, data) {
  const R = data.mine.constants['reach.base'] + s.stats.clickRadius;
  const off = -data.mine.constants['touch.rockOffsetY'];
  const r = s.rocks;
  let best = null;
  let bestN = 0;
  for (let i = 0; i < r.n; i++) {
    if (!(r.hp[i] > 0)) continue;
    let n = 0;
    for (let j = 0; j < r.n; j++) if (r.hp[j] > 0 && Math.abs(r.x[j] - r.x[i]) <= R && Math.abs(r.y[j] - r.y[i]) <= R) n++;
    if (n > bestN) { bestN = n; best = { x: r.x[i], y: r.y[i] + off }; }
  }
  return best;
}

test('бот проходит задания 1–3: олово, бары, кирка', () => {
  const t0 = Date.now();
  const data = loadData();
  const W = makeWorld1(data);
  const up = makeUpgrades(data.upgrades, data.upgraderules, data.strings.strings ?? data.strings);
  const goal = (n) => data.tasks.tables.tasks.rows.find((r) => r[0] === n)[data.tasks.tables.tasks.columns.indexOf('goal')];
  let s = W.init(newGame(data));
  const done = [];
  let pressed = false;
  let cur = null;
  for (let f = 0; f < FRAME_CAP && s.task < 4; f++) {
    const actions = [];
    if (s.taskProgress >= goal(s.task)) { done.push(s.task); actions.push({ kind: 'claim' }); }
    else if (s.task === 2 || s.task === 3) {
      if (s.task === 3 && s.bar[0] >= up.price(0, s.levels, { task: s.task })[0]) actions.push({ kind: 'buy', row: 0 });
      else if (s.ore[0] >= 5 && (s.task === 3 || s.taskProgress < goal(2))) actions.push({ kind: 'craft', bar: 0 });
    }
    // касание: цель выбрана и жива — держим палец, иначе переносим палец (MOVE) на самый плотный камень
    let touch = null;
    const alive = cur && s.rocks.hp.some((h, i) => h > 0 && s.rocks.x[i] === cur.rx && s.rocks.y[i] === cur.ry);
    if (!alive) {
      const tg = target(s, data);
      cur = null;
      if (tg) {
        const i = s.rocks.x.findIndex((x, k) => x === tg.x && s.rocks.y[k] === tg.y - 80 && s.rocks.hp[k] > 0);
        cur = { rx: tg.x, ry: tg.y - 80 };
        touch = { a: pressed ? 2 : 0, x: tg.x, y: tg.y };
        pressed = true;
        assert.ok(i >= 0);
      }
    }
    s = W.frame(s, { touch, actions });
  }
  const wall = Date.now() - t0;
  assert.deepEqual(done, [1, 2, 3], `закрыты задания ${done}; кадр ${s.frame}, task ${s.task}, progress ${s.taskProgress}`);
  assert.equal(s.task, 4);
  assert.equal(s.levels[0], 1, 'кирка уровня 1');
  assert.equal(s.stats.pickaxeDamage, 3, 'pickaxeDamage после покупки кирки');
  assert.ok(wall <= 60000, `wall ${wall} мс`);
  console.log(`задания 1–3 закрыты за ${s.frame} кадров, ${wall} мс; level ${s.level}, xp ${s.xp}`);
});

test('новый экран без раскладки и без ГСЧ — ошибка', () => {
  const data = loadData();
  const W = makeWorld1(data);
  const s0 = newGame(data);
  delete s0.rng;
  s0.rocks.hp.fill(0);
  let s = W.init(s0);
  assert.throws(() => { for (let i = 0; i < 80; i++) s = W.frame(s, { touch: null, actions: [] }); }, /раскладк/);
});
E
